(function(){
'use strict';
const $=id=>document.getElementById(id),api=window.TadaaApi;
let sampleMode=false,user=null,orgs=[],eligible={},events=[],orders=[],tickets=[],favorites=[],route='inicio',selected=null,orderPending=null,orgSelected=null,membershipInfo=null,notifications=[],selectedSeatIds=[],paymentMode='internal_test',account=null,nowList=[],selectedAddons={};
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pesos=n=>new Intl.NumberFormat('es-MX',{style:'currency',currency:'MXN',maximumFractionDigits:0}).format((Number(n)||0)/100);
function message(text){const el=$('message');el.textContent=text;el.classList.add('on');clearTimeout(message.t);message.t=setTimeout(()=>el.classList.remove('on'),5200)}
function banner(x){return `<div class="notice">${esc(x)}</div>`}
const date=x=>x?new Date(x).toLocaleString('es-MX',{dateStyle:'medium',timeStyle:'short'}):'Por anunciar';
const ICON_NOW='<svg viewBox="0 0 24 24" fill="#0B0A1C" aria-hidden="true"><path d="M13 2 4 14h7l-1 8 9-12h-7z"/></svg>',ICON_GOLD='<svg viewBox="0 0 24 24" fill="none" stroke="#2A1A00" stroke-width="2.2" aria-hidden="true"><path d="M3 7h18v4a2 2 0 0 0 0 4v4H3v-4a2 2 0 0 0 0-4z"/></svg>';
const eventIcons=e=>{const m=e.metadata||{},o=[];if(m.now_enabled)o.push(`<span class="tv-ic now" title="Now! disponible" role="img" aria-label="Now! disponible">${ICON_NOW}</span>`);if(m.golden_enabled)o.push(`<span class="tv-ic gold" title="Golden Ticket activo" role="img" aria-label="Golden Ticket activo">${ICON_GOLD}</span>`);if(m.tadaa_original)o.push('<span class="tv-ic orig" title="TADAA! Original" role="img" aria-label="TADAA! Original">t!</span>');return o.length?`<div class="tv-icons">${o.join('')}</div>`:''};
const eventPoster=e=>{const img=e.poster_url?`<img src="${esc(e.poster_url)}" alt="" onerror="this.remove()">`:'';return `<article class="show" data-event="${esc(e.id)}"><div class="art" style="--a:#344f20;--b:#111">${img}</div><div class="shade"></div><div class="si"><div class="bg"><span class="pill">${esc(e.metadata?.category||'Experiencias')}</span>${e.sample?'<span class="off">MUESTRA</span>':e.picks?'<span class="off">TADAA! Picks</span>':''}</div>${eventIcons(e)}<h3>${esc(e.title)}</h3><div class="s2">${esc(e.venue||'Ubicación pendiente')}</div><div class="wh">${date(e.starts_at)}</div><div class="ft"><div><small>Desde</small><b>${e.from_price_minor==null?'Consultar':pesos(e.from_price_minor)}</b></div><span class="go">↗</span></div></div></article>`};
const head=(eyebrow,title,lead='')=>`<div class="eb">${esc(eyebrow)}</div><h1 class="pt">${title}</h1>${lead?`<p class="intro-text">${esc(lead)}</p>`:''}`;
const empty=(title,content)=>`<div class="empty-state"><h3>${esc(title)}</h3><p>${esc(content)}</p></div>`;
function tile(title,desc,value){return `<div class="stat"><small>${esc(title)}</small><b>${esc(value)}</b><p class="tiny">${esc(desc)}</p></div>`}
function home(){return `<div class="hello"><div>${head('TU TADAA!',`¡Hola, ${esc((user.full_name||'').split(' ')[0])}!`,'Descubre experiencias y disfruta tus beneficios de forma sencilla.')}</div><button class="btn" data-route="explorar">Explorar cartelera ↗</button></div>${pajarito()}${nowList.length?`<h2 class="sh">Now! · último minuto</h2><div class="now-list">${nowList.slice(0,2).map(c=>nowCard(c)).join('')}</div>`:''}<div class="stats">${tile('ACCESO',eligible.member?'Membresía activa':eligible.company?'Convenio aprobado':'Activa tu acceso',eligible.member?'Suscripción':'TADAA!')}${tile('EVENTOS',sampleMode?'De muestra':'Publicados',events.length)}${tile('MIS BOLETOS','Emitidos',tickets.length)}</div><h2 class="sh">TADAA! Picks</h2><div class="grid4">${events.filter(e=>e.picks).map(eventPoster).join('')||empty('Picks próximamente','Estamos preparando nuestra selección editorial.')}</div><h2 class="sh">Próximas experiencias</h2><div class="rail">${events.slice(0,10).map(eventPoster).join('')||empty('Próximamente','Cuando publiquemos eventos, aparecerán aquí.')}</div><div class="mini-nav"><a href="partner.html">¿Representas a un partner?</a><a href="#/membresia">Consultar membresía</a></div>`}
function explore(){return `${head('CARTELERA','Explora','Encuentra conciertos, teatro y experiencias que te muevan.')}<div class="tools"><input class="tada-select" id="filter" placeholder="Filtrar eventos" value="${esc($('search')?.value||'')}"></div><div class="category-pills" id="categoryPills">${['Todas','Teatro','Conciertos','Musicales','Comedia','Familia','Cultura','Gastronomía','Experiencias'].map(x=>`<button type="button" class="chip ${(!selected?.category&&x==='Todas')||selected?.category===x?'on':''}" data-category="${esc(x==='Todas'?'':x)}">${esc(x)}</button>`).join('')}</div><div id="grid" class="grid4">${events.map(eventPoster).join('')||empty('Aún no hay eventos publicados','En cuanto el equipo publique un evento aparecerá aquí.')}</div>`}
function renderGrid(){let q=($('filter')?.value||'').trim().toLowerCase(),cat=$('categoryPills [data-category].on')?.dataset.category||'';$('grid').innerHTML=events.filter(e=>(!q||e.title.toLowerCase().includes(q))&&(!cat||e.metadata?.category===cat||((cat==='Musicales'||cat==='Comedia')&&String(e.metadata?.category||'').toLowerCase().includes(cat.toLowerCase())))).map(eventPoster).join('')||empty('Sin resultados','Prueba con otra categoría.');}

function eventView(){
 if(!selected)return empty('Evento no encontrado','Regresa a Explorar.');
 const e=selected.event,types=selected.ticketTypes||[];
 const instructions=Array.isArray(e.instructions)?e.instructions:[];
 const favoriteButton=e.sample?'':`<button class="btn ghost" data-fav="${esc(e.id)}">${favorites.includes(e.id)?'♥ Guardado':'♡ Me interesa'}</button>`;
 const promo=e.ticketing_mode==='tadaa'&&e.membership_promo_enabled?`<div class="notice"><b>Beneficio incluido:</b> esta compra elegible incluye ${Number(e.membership_promo_days)||30} días de acceso TADAA! Membership para la cuenta compradora.</div>`:'';
 return `<button class="back" data-route="explorar">← Volver a cartelera</button><div class="ev"><div><div class="hero" style="--a:#2e4a18;--b:#101910"><div class="art">${e.hero_url?`<img src="${esc(e.hero_url)}" alt="">`:''}</div>${eventIcons(e)}${e.metadata?.logo_url?`<img class="tv-logo-img ev-logo" src="${esc(e.metadata.logo_url)}" alt="${esc(e.title)}">`:`<h1>${esc(e.title)}</h1>`}</div><div class="facts"><div class="fact"><small>FECHA</small><b>${date(e.starts_at)}</b></div><div class="fact"><small>SEDE</small><b>${esc(e.venue||'Por anunciar')}</b></div></div><p class="desc">${esc(e.description||'')}</p>${promo}<h2 class="sh">Antes del evento</h2><div class="how">${instructions.map((x,i)=>`<div><b>${i+1}</b><span>${esc(x)}</span></div>`).join('')||'<div>Las instrucciones de acceso se publicarán antes de la función.</div>'}</div>${selected.seats?.length?`<h2 class="sh">Selecciona tus asientos</h2><div class="seat-map">${selected.seats.map(s=>`<button type="button" class="seat ${selectedSeatIds.includes(s.id)?'on':''}" data-seat="${esc(s.id)}" title="${esc(s.section_name)} ${esc(s.row_label||'')} ${esc(s.seat_label)}">${esc(s.seat_label)}</button>`).join('')}</div><p class="tiny">${selectedSeatIds.length} asientos seleccionados. El inventario se confirma al reservar.</p>`:''}${e.maps_url?`<p><a class="link" href="${esc(e.maps_url)}" target="_blank" rel="noopener">Cómo llegar ↗</a></p>`:''}${e.spotify_url?`<p><a class="link" href="${esc(e.spotify_url)}" target="_blank" rel="noopener">Escuchar en Spotify ↗</a></p>`:''}<h2 class="sh">También te puede interesar</h2><div class="grid4">${events.filter(x=>x.id!==e.id).slice(0,3).map(eventPoster).join('')}</div></div><aside class="sel-c"><h3>${e.sample?'Evento ilustrativo':'Entradas'}</h3><p class="mut">${e.sample?'Solo contenido de muestra':e.ticketing_mode==='tadaa'?'Venta administrada por TADAA!': 'Boletaje externo: consulta el enlace oficial.'}</p>${e.sample?'<div class="notice">Este evento es ficticio. No se pueden reservar ni comprar entradas.</div>':''}${nowBlock()}${types.filter(t=>!t.now).map(t=>`<div class="zn"><div class="n"><b>${esc(t.name)}</b><small>Disponibles: ${t.available??Math.max(0,t.quantity_total-t.quantity_reserved)}${t.member_only?' · Requiere membresía/convenio':''}</small></div><div class="p"><b>${pesos(t.price_minor)}</b></div><button class="btn sm" data-type="${esc(t.id)}" ${t.member_only&&!eligible.member&&!eligible.company?'disabled':''}>Elegir</button></div>`).join('')||(types.length?'':'<p class="mut">La venta aún no está habilitada para este evento.</p>')}${addonsBlock()}${goldenNote()}<p class="tiny">${e.ticketing_mode==='tadaa'?'El checkout se encuentra en entorno privado de pruebas; no hay cargos bancarios.':'Las entradas se consultan en la boletera externa responsable.'}</p>${favoriteButton}</aside></div>`;
}
function orderPrompt(typeId,maxQ=8,isNow=false){const seats=[...selectedSeatIds],adds=addonsPayload(),d=document.createElement('div');d.className='ov on';d.innerHTML=`<div class="md"><button class="x" id="closeOrder">✕</button><h3>${isNow?'Now! · ¿Cuántos lugares?':'¿Cuántos lugares?'}</h3><div class="field"><label>Cantidad ${seats.length?'(asientos seleccionados)':`(máximo ${maxQ})`}</label><input id="quantity" type="number" value="${seats.length||1}" min="1" max="${maxQ}" ${seats.length?'readonly':''}></div>${adds.length?`<p class="tiny">Add-ons: ${adds.map(a=>a.quantity+'× '+esc((selected?.addons||[]).find(x=>x.id===a.id)?.title||'')).join(', ')}</p>`:''}${isNow?'<p class="tiny">Los primeros en pagar se quedan con los lugares: tu reserva no aparta el cupo Now! si no pagas.</p>':''}${seats.length?`<p class="tiny">Asientos: ${seats.length}</p>`:''}<button class="btn" id="createOrder">Solicitar reserva</button><p class="tiny">La reserva tendrá un vencimiento de 15 minutos.</p></div>`;document.body.appendChild(d);d.querySelector('#closeOrder').onclick=()=>d.remove();d.querySelector('#createOrder').onclick=async()=>{try{const quantity=Number(d.querySelector('#quantity').value);if(seats.length&&seats.length!==quantity)throw new Error('Selecciona exactamente un asiento por boleto.');const x=await api.call('/api/v2/orders','POST',{ticketTypeId:typeId,quantity,idempotencyKey:crypto.randomUUID(),...(seats.length?{seatIds:seats}:{}),...(adds.length&&!isNow?{addons:adds}:{})});d.remove();selectedSeatIds=[];selectedAddons={};message('Reserva creada. Completa el pago de prueba en Mis reservas.');await load();go('reservas')}catch(e){message(e.message)}}}
function reservations(){return head('TU ACTIVIDAD','Mis reservas','Pedidos guardados en la base de datos de TADAA!.')+`<div class="rl">${orders.map(o=>`<div class="rr"><div><div class="eb">${esc(o.status.toUpperCase())}</div><h4>Pedido ${esc(o.id.slice(0,8))}</h4><p class="mut">${date(o.created_at)}</p></div><div class="act"><b>${pesos(o.total_minor)}</b>${o.status==='pending'?`${o.provider==='clip-checkout-v2'&&o.payment_status==='pending'?`<span class="st conf">Esperando confirmación segura de Clip. No vuelvas a pagar.</span>`:paymentMode==='clip'?`<button class="btn sm" data-pay-clip="${o.id}">Continuar con Clip</button>`:`<button class="btn sm" data-pay="${o.id}">Pagar en entorno de prueba</button>`}`:''}${o.status==='paid'?`<button class="btn ghost sm" data-refund-request="${o.id}">Solicitar devolución</button>`:''}</div></div>`).join('')||empty('Todavía no hay reservas','Cuando reserves un evento, aparecerá aquí.')}</div>`}
function interests(){return head('TUS GUSTOS','Me interesa','Eventos que has guardado para revisar después.')+`<div class="grid4">${events.filter(e=>favorites.includes(e.id)).map(eventPoster).join('')||empty('Nada guardado todavía','Pulsa el corazón en un evento que te guste.')}</div>`}
function membership(){const ent=(membershipInfo?.entitlements||[]).filter(x=>x.status==='active');const m=membershipInfo?.membership;const until=m?.ends_at||ent[0]?.ends_at;return head('TU ACCESO','Membresía','Tu acceso individual, promocional o mediante convenio, siempre visible y bajo tu control.')+pajarito()+`<div class="two"><div class="box"><h3 class="title-s">TADAA! Membership</h3><p class="mut">Beneficios, descuentos y experiencias de acuerdo con tu modalidad de acceso.</p>${exitOffer()?`<h2>${pesos(Math.round(10000*(100-exitOffer().discount_pct)/100))} <small style="font-size:15px;color:#888">/ mes · <s>${pesos(10000)}</s></small></h2><p class="st conf">${exitOffer().discount_pct}% de descuento por ${exitOffer().months_total-exitOffer().months_used} meses</p>`:`<h2>${pesos(10000)} <small style="font-size:15px;color:#888">/ mes</small></h2>`}${eligible.company?'<p class="st conf">Acceso activo mediante convenio empresarial.</p>':eligible.member?`<p class="st paid">Acceso activo</p><p class="mut">Vigente hasta: ${date(until)}</p>${m?.status==='active'?'<button class="btn ghost" id="cancelMember">Cancelar al finalizar el periodo</button>':''}`:`<button class="btn" id="joinMember">Obtener membresía</button>`}<p class="tiny">Si compraste un boleto TADAA! elegible, tus 30 días promocionales aparecen aquí.</p></div><div class="box"><h4>Renovación y transparencia</h4>${banner('La renovación automática no está activa. El pago de prueba no genera cargos bancarios. La renovación recurrente de Clip se habilitará cuando la integración comercial y los webhooks estén certificados.')}${m?.status==='active'?`<label class="chip"><input type="checkbox" id="renewAuth" ${m.auto_renew_authorized?'checked':''}> Autorizo que TADAA! guarde mi preferencia de renovación cuando el cobro recurrente esté habilitado.</label><button class="btn ghost" id="saveRenewal">Guardar preferencia</button>`:''}</div></div>`}
function wallet(){return head('TU WALLET','Wallet y cashback','Consulta el saldo y las recompensas que ya están disponibles.')+`<div id="walletSummary" class="stats">Cargando saldo…</div><div class="box"><h3>Movimientos y recompensas</h3><p class="mut">El cashback de una compra elegible queda pendiente hasta que termine el evento y después se libera según las reglas vigentes.</p></div>`}
function golden(){return head('EXPERIENCIAS EXCLUSIVAS','Golden Ticket & TADAA! Awards','Participa en experiencias especiales y celebra lo mejor del entretenimiento.')+`<h2 class="sh">Golden Ticket</h2><div id="goldenCampaigns" class="grid4">Cargando experiencias…</div><h2 class="sh">TADAA! Awards</h2><div id="awardsPrograms" class="grid4">Cargando programas…</div><div class="box"><h3>Propón una nominación</h3><form id="awardNomination"><div class="field"><label>Programa</label><select id="awardProgram"></select></div><div class="field"><label>Categoría</label><input name="category" required></div><div class="field"><label>Producción / persona nominada</label><input name="title" required></div><div class="field"><label>Motivo</label><textarea name="description"></textarea></div><button class="btn">Enviar nominación</button></form></div>`}
function merch(){return head('TIENDA TADAA!','Merchandising','Productos oficiales y artículos asociados a experiencias.')+`<div id="merchProducts" class="grid4">Cargando tienda…</div>`}
function profile(){return head('TU CUENTA','Mi perfil','Administra tus datos y preferencias.')+`<div class="pf"><div class="box pc"><div class="av" style="width:90px;height:90px;font-size:26px;margin:auto">${esc((user.full_name||'T').slice(0,1))}</div><h3>${esc(user.full_name)}</h3><p>${esc(user.email)}</p><button class="btn ghost" id="profileLogout">Cerrar sesión</button></div><div class="sec2">${accountBox()}<div class="box"><h4>Preferencias</h4><p class="tiny">Se guardan en PostgreSQL y se utilizarán para tus recomendaciones.</p><div class="chips" id="prefs">${['Teatro','Conciertos','Musicales','Cine','Gastronomía','Familia','Cultura','Deportes','Experiencias'].map(v=>`<button class="chip ${(user.interests||[]).includes(v)?'on':''}" data-pref="${v}">${v}</button>`).join('')}</div><button class="btn" id="savePrefs" style="margin-top:22px">Guardar gustos</button></div><div class="box"><h4>Tu modalidad de acceso</h4><p>${eligible.company?'Convenio empresarial aprobado':eligible.member?'Membresía individual activa':'Acceso pendiente de aprobación o pago'}</p></div></div></div>`}
function company(){if(!orgSelected)return empty('Sin empresa asociada','Tu cuenta todavía no administra una organización.');return head('PORTAL EMPRESARIAL',esc(orgSelected.name),'Altas y bajas con validación. Una baja solo pausa beneficios: la cuenta del colaborador se conserva.')+companyExtras()+`<div class="box"><h4>Padrón de colaboradores</h4><p class="tiny">Carga CSV o XLSX con encabezados employee_code,given_name,rfc para ALTAS (el RFC evita cuentas duplicadas). Para BAJAS utiliza employee_code. Hasta 5,000 registros por operación.</p><div class="columns"><div><div class="title-s">ALTAS</div><input class="input-file" type="file" accept=".csv,.xlsx,text/csv,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" id="upAltas"><button class="btn sm" data-import="altas">Revisar altas</button></div><div><div class="title-s">BAJAS</div><input class="input-file" type="file" accept=".csv,.xlsx,text/csv,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" id="upBajas"><button class="btn ghost sm" data-import="bajas">Revisar bajas</button></div></div><div id="importReview"></div></div><h2 class="sh">Colaboradores</h2><div class="box"><div id="employees">Cargando padrón…</div></div>`}
function producer(){return head('PORTAL DE PRODUCTORES',esc(orgSelected.name),'Administra tus producciones, consulta ventas y prepara la operación de acceso.')+`<div id="producerStats" class="stats"></div><div class="two"><div class="box"><h4>Ventas por evento</h4><div id="producerSales">Cargando…</div></div><div class="box"><h4>Liquidaciones</h4><div id="producerSettlements">Cargando…</div></div></div><div class="two"><div class="box"><h4>Proponer evento</h4><form id="producerEvent"><div class="field"><label>Nombre</label><input name="title" required></div><div class="field"><label>Slug</label><input name="slug" placeholder="evento-unico-2027" required></div><div class="field"><label>Descripción</label><textarea name="description"></textarea></div><div class="field"><label>Categoría</label><select name="category"><option>Conciertos</option><option>Teatro</option><option>Experiencias</option></select></div><div class="field"><label>Fecha</label><input name="startsAt" type="datetime-local"></div><div class="field"><label>Boletera</label><select name="ticketingMode"><option value="external">Boletera externa</option><option value="tadaa">TADAA! Tickets</option></select></div><label class="chip"><input name="membershipPromoEnabled" type="checkbox" value="true"> Incluir 30 días de TADAA! por compra elegible</label><button class="btn">Enviar evento a revisión</button></form></div><div class="box"><h4>Mis eventos</h4><div id="producerEvents">Cargando…</div><p class="tiny">La publicación, inventario y venta requieren aprobación y configuración de TADAA!.</p></div></div><div class="box" style="margin-top:20px"><h4>Control de acceso</h4><p class="tiny">La validación de QR está disponible para eventos publicados de tu organización y requiere sesión autorizada.</p><div class="field"><label>Evento</label><select id="checkinEvent"></select></div><div class="field"><label>QR escaneado / token</label><textarea id="producerQr" rows="3"></textarea></div><button class="btn" id="producerCheckin">Validar entrada</button><div id="producerCheckinResult"></div></div>${producerExtras()}`}
const DELIVERY={provisional:['PASE PROVISIONAL','prov','Tu lugar está confirmado. El boleto final llega antes del evento.'],delivering:['EN ENTREGA','deliv','Estamos emitiendo tu boleto con la boletera oficial.'],final:['BOLETO FINAL','paid','Muestra este QR en la entrada.']};
const STEPS=['provisional','delivering','final'];
const folio=id=>'TD-'+String(id||'').replace(/-/g,'').slice(0,8).toUpperCase();
function countdown(to){const ms=new Date(to)-Date.now();if(ms<=0)return 'ya';const h=Math.floor(ms/3600000),m=Math.floor(ms%3600000/60000),s=Math.floor(ms%60000/1000);return (h?h+'h ':'')+String(m).padStart(2,'0')+'m '+String(s).padStart(2,'0')+'s'}
const exitOffer=()=>(account?.offers||[]).find(o=>o.kind==='company_exit')||(account?.offers||[])[0]||null;
function pajarito(){const o=exitOffer();if(!o||eligible.member)return '';return `<div class="pajarito"><span class="pj-bird" aria-hidden="true">🐦</span><div><b>Un pajarito nos contó…</b><p>Tus beneficios de convenio se pausaron, pero tu cuenta y tus boletos siguen aquí. Te regalamos ${o.months_total-o.months_used} meses de membresía al ${o.discount_pct}%.</p></div><button class="tv-btn" data-route="membresia">Activar por ${pesos(Math.round(10000*(100-o.discount_pct)/100))}/mes</button></div>`}
function nowCard(c,compact){const st=c.state;const action=st==='upcoming'?(c.signed?`<button class="tv-btn ghost" data-now-cancel="${c.id}">✓ Registrado · cancelar</button>`:`<button class="tv-btn now" data-now-signup="${c.id}">Registrarme a Now!</button>`):c.signed===false?'<p class="tiny">El registro cerró cuando abrió la venta.</p>':(c.remaining??1)>0?`<button class="tv-btn now" data-now-buy="${c.ticket_type_id}" data-now-max="${c.max_per_user}">¡Comprar ahora!</button>`:'<p class="st past">Agotado: los primeros en pagar se los llevaron</p>';
 return `<article class="now-card ${st} ${compact?'compact':''}"><div class="now-in">${compact?'':`<div class="tv-icons"><span class="tv-ic now">${ICON_NOW}</span></div><small class="now-when">${esc(c.function_label||date(c.starts_at))}</small><h3>${esc(c.title)}</h3><p class="now-sub">${esc(c.venue||'')}${c.venue?' · ':''}${esc(c.ticket_type)}</p>`}${compact?`<div class="now-head"><span class="tv-ic now">${ICON_NOW}</span><b>Now! · ${esc(c.ticket_type)}</b></div>`:''}<div class="now-row"><div><small>PRECIO NOW!</small><b>${pesos(c.price_minor)}</b>${c.regular_price_minor&&Number(c.regular_price_minor)>Number(c.price_minor)?`<s>${pesos(c.regular_price_minor)}</s>`:''}</div><div><small>${st==='open'?'QUEDAN':'ABRE EN'}</small><b ${st==='upcoming'?`data-countdown="${esc(c.opens_at)}"`:''}>${st==='open'?(c.remaining??'—')+' / '+c.quota:countdown(c.opens_at)}</b></div><div><small>REGISTRADOS</small><b>${c.signups}</b></div></div>${action}<p class="tiny">Máximo ${c.max_per_user} por persona · cupo ${c.quota} · solo registrados</p></div></article>`}
function nowView(){return head('ÚLTIMO MINUTO','Now!','Regístrate antes de que abra. Cuando abre, solo los registrados pueden comprar y los primeros en pagar se llevan los lugares.')+`<div class="now-list">${nowList.map(c=>nowCard(c)).join('')||empty('Sin Now! activos','Cuando un evento active venta de último minuto aparecerá aquí.')}</div>`}
function ticketCard(t){const used=t.status!=='valid',d=DELIVERY[t.delivery_status]||DELIVERY.final,idx=STEPS.indexOf(t.delivery_status||'final'),gold=t.golden&&t.golden_revealed_at,qr=!used&&t.qrPayload,b=t.golden_benefit||{};
 const addons=(t.addons||[]).length?`<div class="tk-addons"><small>ADD-ONS</small>${t.addons.map(a=>`<span class="${a.delivered_at?'done':''}">${a.delivered_at?'✓ ':''}${esc(a.quantity)}× ${esc(a.title)}</span>`).join('')}</div>`:'';
 return `<div class="tk ${gold?'gold':''} ${used?'used':''}"><div class="bn ${used?'past':d[1]}">${used?'BOLETO UTILIZADO':d[0]}<small>${t.ticketing_mode==='tadaa'?'TADAA! Tickets':'Boletera oficial'}</small></div>${t.ticketing_mode==='tadaa'&&idx===2?'':`<div class="tk-steps">${STEPS.map((s,i)=>`<span class="${i<=idx?'on':''}">${['Provisional','En entrega','Final'][i]}</span>`).join('')}</div>`}<div class="art">${t.logo_url?`<img class="tv-logo-img" src="${esc(t.logo_url)}" alt="${esc(t.title)}">`:`<b>${esc(t.title)}</b>`}${gold?'<span class="gold-tag">GOLDEN</span>':''}</div><div class="rows"><div><small>EVENTO</small><b>${esc(t.title)}</b></div><div><small>FECHA</small><b>${date(t.starts_at)}</b></div><div><small>SEDE</small><b>${esc(t.venue||'Por anunciar')}</b></div><div><small>ZONA</small><b>${esc(t.ticket_type||'General')}</b></div>${t.seat_label?`<div><small>ASIENTO</small><b>${esc(t.section_name)} · ${esc(t.row_label||'')} ${esc(t.seat_label)}</b></div>`:''}</div>${gold?`<div class="golden-benefit"><small>TU BENEFICIO GOLDEN</small><b>${esc(b.title||'Beneficio Golden')}</b>${b.detail?`<span>${esc(b.detail)}</span>`:''}</div>`:t.golden?`<button class="tv-btn gold-btn" data-reveal="${t.id}">✦ Abrir Golden Ticket</button>`:''}${addons}<div class="perf"></div>${qr?`<img class="ticket-qr" src="/api/v2/tickets/${t.id}/qr?ts=${Date.now()}" alt="Código QR dinámico para validación"><p class="tiny qr-note">QR dinámico · se renueva en <b data-qr-tick>60</b>s · no sirve en captura de pantalla</p>`:!used?`<p class="tiny tk-msg">${esc(d[2])}${t.external_reference?' · Folio boletera: '+esc(t.external_reference):''}</p>`:''}<div class="fo">FOLIO ${folio(t.order_id)}</div></div>`}
function ticketView(){const g=tickets.filter(t=>t.golden&&!t.golden_revealed_at);return head('TUS EXPERIENCIAS','Mis boletos','Pase provisional → en entrega → boleto final. El QR dinámico se renueva cada minuto.')+(g.length?`<div class="golden-cta"><span class="tv-ic gold">${ICON_GOLD}</span><b>¡Tienes ${g.length} Golden Ticket${g.length>1?'s':''} sin abrir!</b><button class="tv-btn" data-reveal="${g[0].id}">Abrir ahora ✦</button></div>`:'')+`<div class="tks">${tickets.map(ticketCard).join('')||empty('No tienes boletos','Completa una reserva y su pago de prueba para emitir uno.')}</div>`}
async function reveal(id){const r=await api.call('/api/v2/tickets/'+id+'/reveal','POST',{});const b=r.benefit||{};const d=document.createElement('div');d.className='golden-ov';d.innerHTML=`<div class="g-rays"></div><div class="g-bokeh"><i></i><i></i><i></i><i></i><i></i><i></i></div><div class="g-stage"><div class="g-ticket"><div class="g-face"><span>GOLDEN TICKET</span><b>tadaa<em>!</em></b><small>1 de cada 100</small></div></div><div class="g-copy"><small>TU BENEFICIO</small><h2>${esc(b.title||'Beneficio Golden')}</h2><p>${esc(b.detail||'Te contactaremos para coordinarlo antes del evento.')}</p><button class="tv-btn" id="gClose">¡Lo quiero!</button></div></div>`;document.body.appendChild(d);requestAnimationFrame(()=>requestAnimationFrame(()=>d.classList.add('on')));d.querySelector('#gClose').onclick=async()=>{d.classList.remove('on');setTimeout(()=>d.remove(),300);await load();go('boletos')}}
function addonsBlock(){const a=selected?.addons||[];if(!a.length||selected.event.ticketing_mode!=='tadaa')return '';return `<div class="addons"><h4>Agrega a tu plan</h4>${a.map(x=>`<div class="addon"><div><b>${esc(x.title)}</b><small>${esc(x.description||({merch:'Merch oficial',combo:'Combo',food:'Alimentos',experience:'Experiencia',parking:'Estacionamiento'}[x.kind]||x.kind))} · ${x.available>0?pesos(x.price_minor):'Agotado'}</small></div><div class="stepper"><button type="button" data-addon-dec="${x.id}" aria-label="Quitar">−</button><span id="ad-${x.id}">${selectedAddons[x.id]||0}</span><button type="button" data-addon-inc="${x.id}" data-addon-max="${Math.max(0,Math.min(x.max_per_order,x.available))}" aria-label="Agregar">+</button></div></div>`).join('')}<p class="tiny">Se suman al pedido de tu boleto y se entregan en el evento.</p></div>`}
function goldenNote(){const g=selected?.golden;if(!g)return '';return `<div class="golden-note"><span class="tv-ic gold">${ICON_GOLD}</span><div><b>Golden Ticket activo</b><small>1 de cada ${Number(g.odds)||100} boletos se vuelve dorado al emitirse: ${esc(g.benefit_title)}.</small></div></div>`}
function nowBlock(){const n=selected?.now||[];if(!n.length)return '';const e=selected.event;return n.map(c=>nowCard({...c,title:e.title,starts_at:e.starts_at,signed:(nowList.find(x=>x.id===c.id)||{}).signed,remaining:(nowList.find(x=>x.id===c.id)||{}).remaining},true)).join('')}
const addonsPayload=()=>Object.entries(selectedAddons).filter(([,q])=>q>0).map(([id,quantity])=>({id,quantity}));
function accountBox(){const a=account;if(!a)return '';const l=a.level||{};return `<div class="box acct"><div class="acct-top"><div><small class="eb">NIVEL ${l.level||1}</small><h3>${esc(l.name||'Curioso')}</h3></div><b class="xp">${l.xp||0} XP</b></div><div class="bar"><i style="width:${Math.max(4,l.progress||0)}%"></i></div><p class="tiny">${l.nextAt?`${l.nextAt-(l.xp||0)} XP para el siguiente nivel`:'Nivel máximo alcanzado'}</p><div class="badges">${(a.badges||[]).map(b=>`<span class="badge b-${esc(b.key)}">${esc(b.title)}</span>`).join('')||'<span class="tiny">Tus insignias aparecerán con tu primer plan.</span>'}</div><div class="acct-stats"><div><b>${a.stats?.tickets||0}</b><small>boletos</small></div><div><b>${a.stats?.attended||0}</b><small>asistencias</small></div><div><b>${a.stats?.golden||0}</b><small>golden</small></div><div><b>${a.stats?.now||0}</b><small>Now!</small></div></div></div><div class="box"><h4>RFC</h4><p class="tiny">Con tu RFC evitamos cuentas duplicadas: si tu empresa te da de baja y luego te reafilia, tus beneficios se reactivan en esta misma cuenta.</p><div class="rfc-row"><input id="rfcInput" maxlength="15" placeholder="XAXX010101000" value="${esc(a.rfc||'')}" autocomplete="off"><button class="btn sm" id="saveRfc">${a.rfc?'Actualizar':'Guardar'}</button></div></div>`}
async function loadNow(){try{nowList=(await api.call('/api/v2/now')).campaigns||[]}catch{nowList=[]}}
async function loadAccount(){try{account=await api.call('/api/v2/me/account')}catch{account=null}}
function producerExtras(){return `<div class="box" style="margin-top:20px"><div class="row-h"><h4>Compras</h4><div class="row-f"><select id="purchEvent"><option value="">Todos los eventos</option></select><input id="purchQ" placeholder="Nombre, correo o folio"><button class="btn sm ghost" id="purchGo">Buscar</button></div></div><div id="purchTotals" class="stats"></div><div id="purchList" class="tbl">Cargando…</div></div><div class="box" style="margin-top:20px"><div class="row-h"><h4>Now! · Golden Ticket · Add-ons</h4><select id="featEvent"></select></div><div id="featPanel" class="feat">Elige un evento.</div><p class="tiny"><a class="link" href="staff.html">Abrir la app de Staff ↗</a> para escanear QR dinámicos o verificar compras de boletera externa y entregar add-ons.</p></div>`}
async function loadPurchases(){const ev=$('purchEvent')?.value||'',q=$('purchQ')?.value||'';try{const r=await api.call(`/api/v2/orgs/${orgSelected.id}/producer/purchases?eventId=${encodeURIComponent(ev)}&q=${encodeURIComponent(q)}`);$('purchTotals').innerHTML=tile('PEDIDOS','Pagados',r.totals.orders)+tile('VENTA','Bruta',pesos(r.totals.gross_minor))+tile('GOLDEN','Emitidos',r.totals.golden);$('purchList').innerHTML=r.purchases.length?`<table><thead><tr><th>Folio</th><th>Comprador</th><th>Evento</th><th>Boletos</th><th>Add-ons</th><th>Total</th><th>Fecha</th></tr></thead><tbody>${r.purchases.map(p=>`<tr><td><b>${esc(p.folio)}</b>${p.now_campaign_id?' <span class="tv-tag now-tag">Now!</span>':''}${(p.tickets||[]).some(t=>t.golden)?' <span class="tv-tag gold-tag2">Golden</span>':''}</td><td>${esc(p.buyer_name||'—')}<small>${esc(p.buyer_email||'')}</small></td><td>${esc(p.event_title)}</td><td>${p.quantity}</td><td>${(p.addons||[]).map(a=>esc(a.quantity+'× '+a.title)).join('<br>')||'—'}</td><td>${pesos(p.total_minor)}</td><td>${date(p.created_at)}</td></tr>`).join('')}</tbody></table>`:'Sin compras para ese filtro.'}catch(e){$('purchList').textContent=e.message}}
async function loadFeatures(){const ev=$('featEvent')?.value;if(!ev){$('featPanel').textContent='Aún no tienes eventos.';return}try{const r=await api.call(`/api/v2/orgs/${orgSelected.id}/producer/events/${ev}/features`);const g=r.golden||{};$('featPanel').innerHTML=`<div class="feat-col"><h5><span class="tv-ic now">${ICON_NOW}</span> Now!</h5>${r.now.map(n=>`<div class="pr"><div><b>${esc(n.ticket_type)}</b><small>${esc(n.state)} · abre ${date(n.opens_at)} · cupo ${n.quota} · ${n.signups} registrados</small></div><label class="sw"><input type="checkbox" data-now-toggle="${n.id}" ${n.enabled?'checked':''}><i></i></label></div>`).join('')||'<p class="tiny">Sin campañas.</p>'}<form id="nowForm" class="mini-form"><select name="ticketTypeId">${r.ticketTypes.map(t=>`<option value="${t.id}">${esc(t.name)} · ${pesos(t.price_minor)}</option>`).join('')}</select><input name="hoursBefore" type="number" min="1" max="168" placeholder="Abre X horas antes" required><input name="quota" type="number" min="1" placeholder="Cupo" required><input name="price" type="number" min="0" step=".01" placeholder="Precio Now! MXN (opcional)"><input name="maxPerUser" type="number" min="1" max="8" value="2"><button class="btn sm">Activar Now!</button></form></div><div class="feat-col"><h5><span class="tv-ic gold">${ICON_GOLD}</span> Golden Ticket</h5><form id="goldForm" class="mini-form"><label class="sw-l"><span>Activo</span><label class="sw"><input type="checkbox" name="enabled" ${g.enabled?'checked':''}><i></i></label></label><label>1 de cada <input name="odds" type="number" min="2" value="${g.odds||100}"> boletos</label><label>Máx. ganadores <input name="maxWinners" type="number" min="0" value="${g.max_winners??10}"></label><select name="benefitKind">${[['upgrade','Upgrade de sección'],['meet_greet','Meet & greet'],['ticket','Boleto para otro evento'],['custom','Otro beneficio']].map(([k,v])=>`<option value="${k}" ${g.benefit_kind===k?'selected':''}>${v}</option>`).join('')}</select><input name="benefitTitle" placeholder="Título del beneficio" value="${esc(g.benefit_title||'')}" required><textarea name="benefitDetail" rows="2" placeholder="Detalle (cómo se canjea)">${esc(g.benefit_detail||'')}</textarea><button class="btn sm">Guardar Golden</button></form></div><div class="feat-col"><h5>＋ Add-ons</h5>${r.addons.map(a=>`<div class="pr"><div><b>${esc(a.title)}</b><small>${esc(a.kind)} · ${pesos(a.price_minor)} · stock ${a.stock} · vendidos ${a.sold}</small></div><label class="sw"><input type="checkbox" data-addon-toggle="${a.id}" ${a.active?'checked':''}><i></i></label></div>`).join('')||'<p class="tiny">Sin add-ons.</p>'}<form id="addonForm" class="mini-form"><select name="kind"><option value="merch">Merch</option><option value="combo">Combo</option><option value="food">Alimentos</option><option value="experience">Experiencia</option><option value="parking">Estacionamiento</option></select><input name="title" placeholder="Playera oficial, Combo familiar…" required><input name="price" type="number" min="0" step=".01" placeholder="Precio MXN" required><input name="stock" type="number" min="0" placeholder="Stock" required><button class="btn sm">Agregar add-on</button></form></div>`;
 const base=`/api/v2/orgs/${orgSelected.id}/producer`;const done=m=>{message(m);loadFeatures()};
 $('nowForm').onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));try{await api.call(`${base}/events/${ev}/now`,'POST',{ticketTypeId:d.ticketTypeId,hoursBefore:Number(d.hoursBefore),quota:Number(d.quota),maxPerUser:Number(d.maxPerUser),priceMinor:d.price===''?null:Math.round(Number(d.price)*100)});done('Now! activado.')}catch(err){message(err.message)}};
 $('goldForm').onsubmit=async e=>{e.preventDefault();const f=e.target,d=Object.fromEntries(new FormData(f));try{await api.call(`${base}/events/${ev}/golden`,'PUT',{enabled:f.enabled.checked,odds:Number(d.odds),maxWinners:Number(d.maxWinners),benefitKind:d.benefitKind,benefitTitle:d.benefitTitle,benefitDetail:d.benefitDetail});done('Golden Ticket guardado.')}catch(err){message(err.message)}};
 $('addonForm').onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));try{await api.call(`${base}/events/${ev}/addons`,'POST',{kind:d.kind,title:d.title,priceMinor:Math.round(Number(d.price)*100),stock:Number(d.stock)});done('Add-on agregado.')}catch(err){message(err.message)}};
 $('featPanel').onchange=async e=>{const n=e.target.dataset.nowToggle,a=e.target.dataset.addonToggle;try{if(n){await api.call(`${base}/now/${n}`,'PATCH',{enabled:e.target.checked});done(e.target.checked?'Now! encendido.':'Now! apagado.')}if(a){await api.call(`${base}/addons/${a}`,'PATCH',{active:e.target.checked});done('Add-on actualizado.')}}catch(err){message(err.message)}};
}catch(e){$('featPanel').textContent=e.message}}
function companyExtras(){return `<div id="companyStats" class="stats"></div><div class="two"><div class="box"><h4>Alta individual</h4><form id="altaForm" class="mini-form"><input name="employeeCode" placeholder="Número de colaborador" required><input name="givenName" placeholder="Nombre" required><input name="rfc" placeholder="RFC (recomendado)" maxlength="15"><button class="btn sm">Dar de alta</button></form><p class="tiny">Si la persona ya tenía cuenta TADAA! con ese RFC, se reactiva la misma cuenta.</p></div><div class="box"><h4>Lo más visitado</h4><div id="companyTop">Cargando…</div></div></div>`}
async function loadCompany(){try{const r=await api.call(`/api/v2/orgs/${orgSelected.id}/company/stats`);$('companyStats').innerHTML=tile('COLABORADORES','Activos',r.employees.active)+tile('ADOPCIÓN','Con cuenta',r.adoptionPct+'%')+tile('PLANES','Últimos 90 días',r.usage.orders)+tile('BAJAS','Beneficios pausados',r.employees.inactive);$('companyTop').innerHTML=r.topEvents.map(x=>`<div class="pr"><b>${esc(x.title)}</b><small>${x.orders} planes</small></div>`).join('')||'Aún sin planes.'}catch(e){$('companyStats').textContent=e.message}$('altaForm').onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));try{const r=await api.call(`/api/v2/orgs/${orgSelected.id}/company/employees`,'POST',d);message(r.linkedExistingAccount?'Alta lista: reactivamos su cuenta existente por RFC.':'Alta lista.');e.target.reset();loadCompany();showEmployees()}catch(err){message(err.message)}}}

const views={now:nowView,inicio:home,explorar:explore,intereses:interests,reservas:reservations,boletos:ticketView,membresia:membership,wallet,golden,merch,perfil:profile,empresa:()=>orgSelected?.kind==='producer'?producer():company()};
async function fetchEvents(){let r=[];try{r=(await api.call('/api/v2/catalog')).events||[]}catch(e){console.warn('Catálogo no disponible, usando ejemplos locales.')}sampleMode=r.length===0;events=sampleMode?window.TadaaSamples.list():r;}
async function load(){const m=await api.refresh();if(!m.authenticated){Curtain.exitTo('login.html',{fadeOnly:true});return false}user=m.user;orgs=m.organizations||[];eligible=m.eligibility||{};orgSelected=orgs.find(x=>['owner','admin','manager'].includes(x.role))||null;$('orgNav').hidden=!orgSelected;$('orgNav').textContent=orgSelected?.kind==='producer'?'▦  Portal de productor':'▦  Portal empresarial';$('userName').textContent=user.full_name||'TADAA!';$('userEmail').textContent=user.email;$('avatar').textContent=(user.full_name||'T')[0].toUpperCase();const promises=await Promise.allSettled([fetchEvents(),api.call('/api/v2/orders'),api.call('/api/v2/tickets'),api.call('/api/v2/favorites'),api.call('/api/v2/membership'),api.call('/api/v2/notifications'),api.call('/api/v2/payment-mode'),api.call('/api/v2/me/account'),api.call('/api/v2/now')]);if(promises[7].status==='fulfilled')account=promises[7].value;if(promises[8].status==='fulfilled')nowList=promises[8].value.campaigns||[];if(promises[1].status==='fulfilled')orders=promises[1].value.orders;if(promises[2].status==='fulfilled')tickets=promises[2].value.tickets;if(promises[3].status==='fulfilled')favorites=promises[3].value.ids;if(promises[4].status==='fulfilled')membershipInfo=promises[4].value;if(promises[5].status==='fulfilled')notifications=promises[5].value.notifications||[];if(promises[6].status==='fulfilled')paymentMode=promises[6].value.mode||'internal_test';return true}
async function loadWallet(){try{const r=await api.call('/api/v2/wallet');$('walletSummary').innerHTML=tile('CASHBACK DISPONIBLE','MXN',pesos(r.cashback.available_minor))+tile('PENDIENTE','MXN',pesos(r.cashback.pending_minor))+tile('WALLET','Saldo',pesos(r.wallet.balance_minor))}catch(e){$('walletSummary').textContent=e.message}}
async function loadGolden(){try{const [g,a]=await Promise.all([api.call('/api/v2/golden-tickets'),api.call('/api/v2/awards')]);$('goldenCampaigns').innerHTML=(g.campaigns||[]).map(x=>`<div class="box"><span class="eb">GOLDEN TICKET</span><h3>${esc(x.title)}</h3><p>${esc(x.description)}</p><b>${esc(x.prize)}</b><p class="tiny">${x.entries} participantes</p><button class="btn" data-golden="${x.id}">Participar</button></div>`).join('')||empty('No hay experiencias abiertas','Pronto publicaremos nuevas experiencias.');$('awardsPrograms').innerHTML=(a.programs||[]).map(x=>`<div class="box"><span class="eb">TADAA! AWARDS</span><h3>${esc(x.name)}</h3><p class="mut">${esc(x.status)}</p>${(x.nominations||[]).map(n=>`<div class="pr"><div><b>${esc(n.title)}</b><small>${esc(n.category)}</small></div>${x.status==='voting'?`<button class="btn sm" data-vote="${n.id}">Votar</button>`:''}</div>`).join('')}</div>`).join('')||empty('Próximamente','Los programas de premios se anunciarán aquí.');$('awardProgram').innerHTML=(a.programs||[]).filter(x=>x.status==='nominations').map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')||'<option value="">No hay programas recibiendo nominaciones</option>';$('awardNomination').onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));try{if(!$('awardProgram').value)throw new Error('No hay programas abiertos.');await api.call('/api/v2/awards/'+$('awardProgram').value+'/nominations','POST',d);message('Nominación enviada a revisión.');e.target.reset()}catch(err){message(err.message)}}}catch(e){$('goldenCampaigns').textContent=e.message}}
async function loadMerch(){try{const r=await api.call('/api/v2/merch');$('merchProducts').innerHTML=(r.products||[]).map(x=>`<div class="box"><div class="art">${x.image_url?`<img src="${esc(x.image_url)}" alt="">`:''}</div><h3>${esc(x.title)}</h3><p class="mut">${esc(x.description||'')}</p><b>${pesos(x.price_minor)}</b><p class="tiny">Disponibles: ${x.available}</p><button class="btn" data-merch="${x.id}" ${x.available<1?'disabled':''}>Comprar</button></div>`).join('')||empty('Tienda en preparación','Pronto habrá productos disponibles.')}catch(e){$('merchProducts').textContent=e.message}}
function go(to){route=views[to]?to:'inicio';history.replaceState(null,'','#/'+route);Curtain.view(()=>render())}
async function render(){document.querySelectorAll('[data-r]').forEach(b=>b.classList.toggle('on',b.dataset.r===route));$('view').innerHTML=views[route]?.()||home();if(route==='wallet')loadWallet();if(route==='golden')loadGolden();if(route==='merch')loadMerch(); if(route==='explorar'){const f=$('filter');f.oninput=renderGrid;$('categoryPills').onclick=e=>{const b=e.target.closest('[data-category]');if(!b)return;$('categoryPills').querySelectorAll('[data-category]').forEach(x=>x.classList.toggle('on',x===b));renderGrid()}}if(route==='membresia'){$('joinMember')?.addEventListener('click',async()=>{try{const r=await api.call('/api/v2/membership/checkout','POST',{});orderPending=r.orderId;await load();go('reservas');message('Orden de membresía creada. Completa el pago de prueba desde Reservas.')}catch(e){message(e.message)}});$('cancelMember')?.addEventListener('click',async()=>{if(!confirm('¿Cancelar al finalizar el periodo vigente?'))return;try{await api.call('/api/v2/membership/cancel','POST',{});message('Cancelación solicitada al final del periodo.');await load();go('membresia')}catch(e){message(e.message)}});$('saveRenewal')?.addEventListener('click',async()=>{try{await api.call('/api/v2/membership/renewal','POST',{authorize:$('renewAuth').checked});message('Preferencia de renovación guardada. No se programó ningún cargo.');await load();go('membresia')}catch(e){message(e.message)}})}if(route==='perfil'){$('profileLogout').onclick=logout;$('prefs').onclick=e=>e.target.closest('[data-pref]')?.classList.toggle('on');$('savePrefs').onclick=async()=>{try{await api.call('/api/v2/profile','PATCH',{interests:[...document.querySelectorAll('#prefs .on')].map(b=>b.dataset.pref),address:user.address||{}});message('Preferencias guardadas.');await load()}catch(e){message(e.message)}}}if(route==='empresa'){if(orgSelected?.kind==='producer')producerEvents();else{showEmployees();loadCompany()}}if(route==='perfil'&&$('saveRfc'))$('saveRfc').onclick=async()=>{try{const r=await api.call('/api/v2/me/rfc','PUT',{rfc:$('rfcInput').value});message(r.linkedAgreements?'RFC guardado y convenio vinculado.':'RFC guardado.');await loadAccount();go('perfil')}catch(e){message(e.message)}};if(route==='now'||route==='boletos'||route==='inicio')tickTimers();}
async function producerEvents(){if(!orgSelected)return;try{const r=await api.call('/api/v2/orgs/'+orgSelected.id+'/producer/overview');$('producerStats').innerHTML=tile('EVENTOS', 'De tu organización',r.events.length)+tile('PEDIDOS','Pagados',r.sales.reduce((n,x)=>n+Number(x.orders||0),0))+tile('BOLETOS','Emitidos / accesos',`${r.tickets.issued} / ${r.tickets.checked_in}`);$('producerSales').innerHTML=(r.sales||[]).map(x=>`<div class="pr"><div><b>${esc(x.title)}</b><small>${x.orders} pedidos pagados</small></div><b>${pesos(x.gross_minor)}</b></div>`).join('')||'Sin ventas registradas.';$('producerSettlements').innerHTML=(r.settlements||[]).map(x=>`<div class="pr"><div><b>${date(x.period_start)} – ${date(x.period_end)}</b><small>${esc(x.status)}</small></div><b>${pesos(x.net_minor)}</b></div>`).join('')||'Aún no hay liquidaciones calculadas.';$('producerEvents').innerHTML=r.events.map(x=>`<div class="pr"><div><b>${esc(x.title)}</b><small>${esc(x.status)} · ${date(x.starts_at)} · ${esc(x.ticketing_mode)}</small>${x.status==='draft'&&x.ticketing_mode==='tadaa'?`<form class="producer-ticket-type" data-event-ticket="${x.id}"><input name="name" placeholder="Tipo de boleto (General/VIP)" required><input name="price" type="number" min="0" step=".01" placeholder="Precio MXN" required><input name="stock" type="number" min="0" placeholder="Cupo" required><button class="btn sm">Agregar inventario</button></form>`:''}</div></div>`).join('')||'Todavía no has enviado eventos';$('producerEvents').onclick=async e=>{const form=e.target.closest('[data-event-ticket]');if(!form)return;e.preventDefault();const d=Object.fromEntries(new FormData(form));try{await api.call('/api/v2/orgs/'+orgSelected.id+'/events/'+form.dataset.eventTicket+'/ticket-types','POST',{name:d.name,priceMinor:Math.round(Number(d.price)*100),stock:Number(d.stock)});message('Tipo de boleto creado en borrador.');producerEvents()}catch(err){message(err.message)}};const opts=r.events.map(x=>`<option value="${x.id}">${esc(x.title)}</option>`).join('');$('featEvent').innerHTML=opts;$('purchEvent').innerHTML='<option value="">Todos los eventos</option>'+opts;$('featEvent').onchange=loadFeatures;$('purchGo').onclick=loadPurchases;$('purchEvent').onchange=loadPurchases;loadPurchases();loadFeatures();$('checkinEvent').innerHTML=r.events.filter(x=>x.ticketing_mode==='tadaa'&&x.status==='published').map(x=>`<option value="${x.id}">${esc(x.title)}</option>`).join('');$('producerEvent').onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));d.startsAt=d.startsAt?new Date(d.startsAt).toISOString():null;d.membershipPromoEnabled=d.membershipPromoEnabled==='true';try{await api.call('/api/v2/orgs/'+orgSelected.id+'/events','POST',d);message('Evento enviado a revisión.');producerEvents();e.target.reset()}catch(err){message(err.message)}};$('producerCheckin').onclick=async()=>{try{const eventId=$('checkinEvent').value;if(!eventId)throw new Error('No tienes eventos TADAA! publicados.');const result=await api.call('/api/v2/orgs/'+orgSelected.id+'/events/'+eventId+'/checkin','POST',{qrPayload:$('producerQr').value.trim()});$('producerCheckinResult').textContent=result.accepted?'Entrada validada correctamente.':'No se pudo validar.';$('producerQr').value=''}catch(err){$('producerCheckinResult').textContent=err.message}}}catch(err){$('producerEvents').textContent=err.message}}
async function showEmployees(){if(!orgSelected)return;try{const d=await api.call('/api/v2/orgs/'+orgSelected.id+'/company/employees');$('employees').innerHTML=d.employees.length?d.employees.map(e=>`<div class="pr ${e.active?'':'off'}"><div><b>${esc(e.given_name)}</b><small>${esc(e.employee_code)}${e.rfc?' · '+esc(e.rfc):''} · ${e.active?'Activo':'Baja · beneficios pausados'} · ${e.claimed?(e.approved_at?'Aprobado':'Solicitud pendiente'):'Sin cuenta'}</small></div><div class="act">${e.claimed&&e.active&&!e.approved_at?`<button class="btn sm" data-approve="${e.id}">Aprobar</button>`:''}${e.active?`<button class="btn ghost sm" data-baja="${e.id}">Dar de baja</button>`:`<button class="btn sm" data-reactivar="${e.id}">Reactivar</button>`}</div></div>`).join(''):'No hay colaboradores cargados.'}catch(e){$('employees').textContent=e.message}}
async function importCsv(kind){const file=$(kind==='altas'?'upAltas':'upBajas').files[0];if(!file)return message('Selecciona un archivo CSV o XLSX.');try{let payload={kind,filename:file.name};if(file.name.toLowerCase().endsWith('.xlsx')){const bytes=new Uint8Array(await file.arrayBuffer());let bin='';for(let i=0;i<bytes.length;i+=8192)bin+=String.fromCharCode(...bytes.subarray(i,i+8192));payload.xlsxBase64=btoa(bin)}else payload.csv=await file.text();const r=await api.call('/api/v2/orgs/'+orgSelected.id+'/imports','POST',payload);$('importReview').innerHTML=`<div class="notice"><h4>Confirmar ${kind.toUpperCase()}</h4><p>Recibidos ${r.summary.total} · válidos ${r.summary.valid} · rechazados ${r.summary.rejected}.</p><p>La modificación NO se aplica hasta confirmar.</p><label><input type="checkbox" id="allowImport"> Autorizo expresamente esta modificación del padrón de mi organización.</label><div class="field"><label>Escribe CONFIRMAR</label><input id="confirmWord" placeholder="CONFIRMAR"></div><button class="btn" id="confirmImport">Aplicar ${kind}</button></div>`;$('confirmImport').onclick=async()=>{if(!$('allowImport').checked||$('confirmWord').value!=='CONFIRMAR')return message('Debes autorizar y escribir CONFIRMAR.');try{const d=await api.call('/api/v2/orgs/'+orgSelected.id+'/imports/'+r.batchId+'/confirm','POST',{confirm:true,confirmText:'CONFIRMAR'});message(`Padrón actualizado: ${d.changes} registros${d.relinked?` · ${d.relinked} cuentas reactivadas por RFC`:''}${d.exitOffers?` · ${d.exitOffers} avisos “Un pajarito nos contó…”`:''}.`);$('importReview').innerHTML='';showEmployees()}catch(e){message(e.message)}}}catch(e){message(e.message)}}
async function logout(){try{await api.call('/api/v2/auth/logout','POST',{});}finally{Curtain.exitTo('login.html',{fadeOnly:true})}}
async function showEvent(id){try{selectedSeatIds=[];const example=events.find(e=>e.id===id&&e.sample);selected=example?{event:{...example,description:example.details,instructions:['Consulta el acceso cuando el evento sea publicado.']},ticketTypes:[],seats:[]}:await api.call('/api/v2/events/'+id);Curtain.view(()=>$('view').innerHTML=eventView());}catch(e){message(e.message)}}
document.addEventListener('click',async e=>{const seat=e.target.closest('[data-seat]');if(seat){const id=seat.dataset.seat;selectedSeatIds=selectedSeatIds.includes(id)?selectedSeatIds.filter(x=>x!==id):selectedSeatIds.length<8?[...selectedSeatIds,id]:selectedSeatIds;seat.classList.toggle('on',selectedSeatIds.includes(id));return}const b=e.target.closest('[data-now-signup],[data-now-cancel],[data-now-buy],[data-reveal],[data-addon-inc],[data-addon-dec],[data-baja],[data-reactivar],[data-route],[data-r],[data-event],[data-type],[data-pay],[data-pay-clip],[data-fav],[data-import],[data-approve],[data-golden],[data-vote],[data-merch],[data-refund-request]');if(!b)return;try{if(b.dataset.nowSignup||b.dataset.nowCancel){await api.call('/api/v2/now/'+(b.dataset.nowSignup||b.dataset.nowCancel)+'/signup',b.dataset.nowSignup?'POST':'DELETE');message(b.dataset.nowSignup?'¡Listo! Te avisamos cuando abra Now!.':'Registro cancelado.');await loadNow();if(selected&&route!=='now'&&document.querySelector('.sel-c'))$('view').innerHTML=eventView();else go(route);return}if(b.dataset.nowBuy)return orderPrompt(b.dataset.nowBuy,Number(b.dataset.nowMax)||2,true);if(b.dataset.reveal)return await reveal(b.dataset.reveal);if(b.dataset.addonInc||b.dataset.addonDec){const id=b.dataset.addonInc||b.dataset.addonDec,max=Number(b.dataset.addonMax??8);selectedAddons[id]=Math.max(0,Math.min(b.dataset.addonInc?max:8,(selectedAddons[id]||0)+(b.dataset.addonInc?1:-1)));const el=$('ad-'+id);if(el)el.textContent=selectedAddons[id];return}if(b.dataset.baja||b.dataset.reactivar){const on=!!b.dataset.reactivar;if(!on&&!confirm('¿Dar de baja? Solo se pausan sus beneficios; su cuenta y boletos se conservan y recibirá una oferta de membresía.'))return;const r=await api.call('/api/v2/orgs/'+orgSelected.id+'/company/employees/'+(b.dataset.baja||b.dataset.reactivar)+'/'+(on?'reactivate':'deactivate'),'POST',{});message(on?'Beneficios reactivados.':r.exitOfferSent?'Baja aplicada. Le enviamos “Un pajarito nos contó…”.':'Baja aplicada.');showEmployees();loadCompany();return}if(b.dataset.route||b.dataset.r){go(b.dataset.route||b.dataset.r);return}if(b.dataset.event){selectedAddons={};return await showEvent(b.dataset.event)}if(b.dataset.type)return orderPrompt(b.dataset.type);if(b.dataset.pay){if(!confirm('¿Confirmar pago de prueba? No se realizará ningún cargo bancario.'))return;await api.call('/api/v2/checkout/test-pay','POST',{orderId:b.dataset.pay});message('Pago de prueba registrado y boletos emitidos.');await load();go('boletos');return}if(b.dataset.payClip){const r=await api.call('/api/v2/checkout/clip','POST',{orderId:b.dataset.payClip});if(r.checkoutUrl)location.assign(r.checkoutUrl);else message('Clip no devolvió un enlace de pago.');return}if(b.dataset.refundRequest){const reason=prompt('Describe el motivo de tu solicitud de devolución:');if(!reason)return;await api.call('/api/v2/orders/'+b.dataset.refundRequest+'/refund-request','POST',{reason});message('Solicitud enviada. El equipo revisará tu caso.');await load();go('reservas');return}if(b.dataset.golden){await api.call('/api/v2/golden-tickets/'+b.dataset.golden+'/enter','POST',{});message('¡Ya estás participando!');loadGolden();return}if(b.dataset.vote){await api.call('/api/v2/awards/nominations/'+b.dataset.vote+'/vote','POST',{});message('Tu voto fue registrado.');loadGolden();return}if(b.dataset.merch){const r=await api.call('/api/v2/merch/orders','POST',{items:[{productId:b.dataset.merch,quantity:1}]});message('Pedido creado. Completa el pago desde Mis reservas.');await load();go('reservas');return}if(b.dataset.fav){const id=b.dataset.fav,add=!favorites.includes(id);await api.call('/api/v2/favorites','POST',{eventId:id,favorite:add});if(add)favorites.push(id);else favorites=favorites.filter(x=>x!==id);message(add?'Agregado a Me interesa':'Eliminado de Me interesa');await showEvent(id);return}if(b.dataset.import)return await importCsv(b.dataset.import);if(b.dataset.approve){await api.call('/api/v2/orgs/'+orgSelected.id+'/employees/'+b.dataset.approve+'/approve','POST',{});message('Colaborador aprobado.');showEmployees()}}catch(err){message(err.message)}});
function tickTimers(){document.querySelectorAll('[data-countdown]').forEach(el=>{if(el.dataset.countdown)el.textContent=countdown(el.dataset.countdown)})}
let qrLeft=60;setInterval(()=>{tickTimers();if(route==='boletos'){qrLeft=qrLeft<=1?60:qrLeft-1;document.querySelectorAll('[data-qr-tick]').forEach(el=>el.textContent=qrLeft)}},1000);
setInterval(()=>{qrLeft=60;if(route==='boletos'){document.querySelectorAll('img.ticket-qr').forEach(img=>{const url=new URL(img.src,location.origin);url.searchParams.set('ts',String(Date.now()));img.src=url.pathname+url.search;})}},60000);
$('logout').onclick=logout;$('refresh').onclick=async()=>{await load();go(route)};$('search').onkeydown=e=>{if(e.key==='Enter'){go('explorar');setTimeout(()=>{$('filter').value=e.target.value;renderGrid()},300)}};
(async()=>{try{if(await load()){route=location.hash.replace('#/','')||'inicio';if(route.startsWith('evento/')){const id=decodeURIComponent(route.slice(7));route='explorar';render();showEvent(id)}else render();Curtain.enter()}}catch(e){$('view').innerHTML=empty('No fue posible cargar tu cuenta',e.message);Curtain.enter()}})();
})();
